/* =========================================================================
   نقاط توسّع معمارية (Extension Points) — بداية الانتقال إلى بنية متعددة
   الملفات (Opal Real Estate Intelligence Platform). core.js يبقى المحرك
   الأساسي كما هو (محرك الفرص/التمويل/المستثمرين والصناديق) بدون أي تعديل
   على منطقه الداخلي، وكل نظام جديد (Pipeline، Investment Score، Risk Engine،
   Due Diligence، IC Workflow، Data Quality، Audit Trail...) يُبنى في ملف
   مستقل تحت src/features/ ويُسجَّل نفسه هنا عبر دوال التسجيل التالية بدل أن
   يُضاف كوده مباشرة داخل core.js. core.js يستدعي فقط نقاط الالتصاق التالية:
     registerTopbarButton(fn)   — زر إضافي في الشريط العلوي.
     registerBodyView(fn)       — قسم كامل بديل/إضافي في جسم الصفحة الرئيسي
                                   (كل دالة تقرر داخلياً هل تعرض شيئاً أم لا).
     registerDetailSection(fn)  — قسم إضافي داخل مذكرة تفاصيل الفرصة (fn(d,c)).
     registerActionHandler(fn) — معالج إجراء إضافي لنقر data-action؛ يُستدعى
                                  فقط لو لم يتعرّف عليه أي معالج مدمج أعلاه
                                  (fn(action, el, e) => true لو تعامل معه).
     registerAssetLinkGuard(fn) — بوابة خارجية (المرحلة الخامسة، محرك ربط رأس
                                  المال) تُستشار *قبل* ربط فرصة كأصل لصندوق
                                  (if-toggle-asset، اتجاه الربط فقط — الفك غير
                                  مقيَّد أبداً)؛ fn(fund, oppId) تُرجع إما
                                  null/undefined (لا اعتراض) أو {blocked:true,
                                  reason} لمنع الربط مع رسالة توضيحية. لا تُنفَّذ
                                  أي منطق حجب هنا في core.js نفسه — فقط الاستدعاء.
   ========================================================================= */
const _topbarButtonHooks = [];
const _bodyViewHooks = [];
const _detailSectionHooks = [];
const _actionHandlerHooks = [];
const _assetLinkGuardHooks = [];
function registerTopbarButton(fn){ _topbarButtonHooks.push(fn); }
function registerBodyView(fn){ _bodyViewHooks.push(fn); }
function registerDetailSection(fn){ _detailSectionHooks.push(fn); }
function registerActionHandler(fn){ _actionHandlerHooks.push(fn); }
function registerAssetLinkGuard(fn){ _assetLinkGuardHooks.push(fn); }
function renderTopbarExtensions(){ return _topbarButtonHooks.map(fn=>{ try{ return fn()||''; }catch(e){ console.error('topbar extension error:', e); return ''; } }).join(''); }
function renderBodyExtensions(){ return _bodyViewHooks.map(fn=>{ try{ return fn()||''; }catch(e){ console.error('body view extension error:', e); return ''; } }).join(''); }
function renderDetailExtensions(d,c){ return _detailSectionHooks.map(fn=>{ try{ return fn(d,c)||''; }catch(e){ console.error('detail section extension error:', e); return ''; } }).join(''); }
async function checkAssetLinkGuards(fund, oppId){
  for(const fn of _assetLinkGuardHooks){
    try{ const r = await fn(fund, oppId); if(r && r.blocked) return r; }catch(e){ console.error('asset-link guard error:', e); }
  }
  return { blocked:false };
}
async function runExternalActionHandlers(action, el, e){
  for(const fn of _actionHandlerHooks){
    try{ if(await fn(action, el, e)) return true; }catch(err){ console.error('action extension error:', err); }
  }
  return false;
}
/* registerMainView(key, fn) — عرض رئيسي كامل بديل (بنفس مبدأ "المستثمرون والصناديق" القائم
   أصلاً في core.js)، لأنظمة تحتاج شاشة كاملة خاصة بها بدل قسم إضافي صغير (مثال: لوحة خط
   الأنابيب الاستثماري، لوحة المحفظة، لوحة لجنة الاستثمار). mainView (حالة عامة، تُضبط عبر
   setCoreState) تحدد أي عرض مسجَّل هو الظاهر حالياً؛ null = اللوحة الافتراضية كالمعتاد. */
const _mainViews = {};
let mainView = null;
function registerMainView(key, fn){ _mainViews[key] = fn; }
function renderActiveMainView(){ return (mainView && _mainViews[mainView]) ? (_mainViews[mainView]()||'') : null; }

// بريد الحساب الذي يُعامَل دائماً كمسؤول (يقدر يدير قائمة الفريق المصرَّح لهم، ومصرَّح له بالدخول
// دائماً حتى لو قائمة الفريق فاضية أو لسه ما اتعملتلهاش). غيّره هنا لو حبيت تستخدم بريد تاني.
// أكثر من بريد أدمن مسموح — كلاهما بصلاحية كاملة دائمة (حساب Firebase وحساب GitHub منفصلين لنفس المالكة).
// لازم يطابق تماماً قائمة isAdminEmail() في firestore.rules.
const ADMIN_EMAILS = ['opal3k@gmail.com', 'ggocss@gmail.com'];
const ADMIN_EMAIL = ADMIN_EMAILS[0]; // للتوافق مع النصوص القديمة التي تعرض بريد أدمن واحد فقط
function isAdmin(user){ return !!user && !!user.email && ADMIN_EMAILS.includes(user.email.toLowerCase()); }
// أعضاء الفريق (غير الأدمن) يقدروا يعدّلوا/يحذفوا بس الفرص اللي هم نفسهم أضافوها — الأدمن يقدر على كل شيء،
// وأي فرصة قديمة بدون بيانات "أضافها" (من قبل تفعيل هذا القيد) تبقى قابلة للتعديل من الجميع.
function canEditOpp(rec){
  if(!DB) return true;
  if(isAdmin(currentUser)) return true;
  const owner = rec && rec.data && rec.data.meta && rec.data.meta.createdBy;
  if(!owner) return true;
  return !!currentUser && !!currentUser.email && owner.toLowerCase()===currentUser.email.toLowerCase();
}

