function subscribeOpportunities(){
  if(unsubscribeOpportunities) return; // متصلة بالفعل
  oppSnapshotInitialized = false; // أول لقطة قادمة = الحالة الحالية (baseline)، مش "جديد"
  // مزامنة لحظية: أي تعديل يُحفظ في Firestore (من جهازك أو من زميل آخر) يظهر فوراً هنا بدون إعادة تحميل الصفحة.
  unsubscribeOpportunities = DB.collection('opportunities').onSnapshot(snap => {
    accessDenied = false;
    opportunities = snap.docs.map(d => ({ id: d.id, data: d.data() }));
    if(oppSnapshotInitialized){
      snap.docChanges().forEach(ch=>{
        if(ch.type!=='added') return;
        const data = ch.doc.data();
        const addedBy = data && data.meta && data.meta.createdBy;
        // نبلّغ فقط عن فرص أضافها زميل آخر (مش أنا) — حتى ما تتكرر إشعارات على إضافاتي أنا نفسي.
        if(addedBy && currentUser && currentUser.email && addedBy.toLowerCase()!==currentUser.email.toLowerCase()){
          pushRecentActivity({ oppId: ch.doc.id, name: (data.meta&&data.meta.name)||'فرصة بدون اسم', by: addedBy, at: Date.now() });
        }
      });
    } else {
      oppSnapshotInitialized = true;
    }
    render();
  }, err => {
    console.error('Firestore sync error:', err);
    if(err && err.code==='permission-denied'){
      accessDenied = true;
      if(unsubscribeOpportunities){ unsubscribeOpportunities(); unsubscribeOpportunities=null; }
      render();
    }
  });
}

/* ---------------- نشاط حديث / تنبيهات "فرصة جديدة أضافها زميل" ---------------- */
function pushRecentActivity(entry){
  recentActivity.unshift({ id: entry.oppId+'-'+entry.at, oppId: entry.oppId, name: entry.name, by: entry.by, at: entry.at, seen:false });
  if(recentActivity.length>30) recentActivity.length = 30;
  notifyBrowser(entry);
  render();
}
function unreadActivityCount(){ return recentActivity.filter(a=>!a.seen).length; }
function notifyBrowser(entry){
  try{
    if(typeof Notification==='undefined' || Notification.permission!=='granted') return;
    const n = new Notification('🏢 فرصة استثمارية جديدة', {
      body: `${entry.name} — أضافها ${entry.by}`,
      tag: 'reop-'+entry.oppId,
    });
    n.onclick = ()=>{ try{ window.focus(); }catch(e){} openDetailId = entry.oppId; recentActivityOpen=false; markActivitySeen(entry.oppId+'-'+entry.at); render(); };
  }catch(e){ console.error('Browser notification error:', e); }
}
function markActivitySeen(id){ const a = recentActivity.find(x=>x.id===id); if(a) a.seen = true; }
function markAllActivitySeen(){ recentActivity.forEach(a=> a.seen=true); }
function timeAgo(ts){
  const s = Math.max(0, Math.floor((Date.now()-ts)/1000));
  if(s<60) return 'الآن';
  const m = Math.floor(s/60); if(m<60) return `منذ ${m} د`;
  const h = Math.floor(m/60); if(h<24) return `منذ ${h} س`;
  const d = Math.floor(h/24); return `منذ ${d} يوم`;
}

/* ---------------- "من متصل الآن" — تحديث نبضة حضور كل ٢٥ ثانية + متابعة حضور الجميع ---------------- */
function startPresence(){
  if(!DB || !currentUser) return;
  const ref = DB.collection('presence').doc(currentUser.uid);
  const beat = () => ref.set({ email: currentUser.email, lastSeen: firebase.firestore.FieldValue.serverTimestamp() }, { merge:true }).catch(()=>{});
  beat();
  if(presenceHeartbeatTimer) clearInterval(presenceHeartbeatTimer);
  presenceHeartbeatTimer = setInterval(beat, 25000);
  if(!unsubscribePresence){
    unsubscribePresence = DB.collection('presence').onSnapshot(snap => {
      const now = Date.now();
      onlineUsers = snap.docs.map(d=>d.data())
        .filter(u => u.lastSeen && (now - u.lastSeen.toMillis()) < 90000)
        .sort((a,b)=> (a.email||'').localeCompare(b.email||''));
      render();
    }, err => { console.error('Presence sync error:', err); });
  }
}
function stopPresence(){
  if(presenceHeartbeatTimer){ clearInterval(presenceHeartbeatTimer); presenceHeartbeatTimer=null; }
  if(unsubscribePresence){ unsubscribePresence(); unsubscribePresence=null; }
  onlineUsers = [];
}

/* ---------------- لوحة إدارة الفريق (المسؤول فقط) — وصول مؤقت بمدة اختيارية ---------------- */
let unsubscribeAllowlist = null;
const TEAM_DURATIONS = { '7': 'أسبوع', '30': 'شهر', '90': '3 أشهر', 'permanent': 'دائم (بدون انتهاء)' };
function subscribeAllowlistIfAdmin(){
  if(!DB || !currentUser || !isAdmin(currentUser) || unsubscribeAllowlist) return;
  unsubscribeAllowlist = DB.collection('team_members').onSnapshot(snap=>{
    allowlistEmails = snap.docs.map(d=>{
      const v = d.data();
      return { email: d.id, expiresAt: v.expiresAt ? v.expiresAt.toDate() : null };
    }).sort((a,b)=>a.email.localeCompare(b.email));
    render();
  }, err=>{ console.error('Team members sync error:', err); });
}

/* ---------------- العلامة التجارية لتقارير الطباعة/PDF (شعار الشركة + الاسم) — مشتركة لكل الفريق ---------------- */
function subscribeBranding(){
  if(!DB || unsubscribeBranding) return;
  unsubscribeBranding = DB.collection('settings').doc('branding').onSnapshot(doc=>{
    const v = doc.exists? doc.data() : {};
    branding = { companyName: v.companyName||'', logoDataUrl: v.logoDataUrl||'' };
    render();
  }, err=>{ console.error('Branding sync error:', err); });
}
function loadLocalBranding(){
  try{ const raw = localStorageSafe('reop_branding'); if(raw) branding = JSON.parse(raw); }catch(e){}
}
function saveLocalBranding(){ try{ localStorage.setItem('reop_branding', JSON.stringify(branding)); }catch(e){} }
async function saveBranding(patch){
  branding = { ...branding, ...patch };
  if(!DB){ saveLocalBranding(); return; }
  await DB.collection('settings').doc('branding').set(branding, { merge:true });
}

async function initDb(){
  try{
    if(DEMO_MODE){
      console.warn('وضع تجريبي (?demo=1) — Firebase مُتجاهَل عمداً، البيانات محلية في هذا المتصفح فقط.');
      authReady = true;
      loadLocalBranding();
    } else if(window.FIREBASE_CONFIG && window.FIREBASE_CONFIG.apiKey && window.FIREBASE_CONFIG.apiKey !== 'REPLACE_ME'){
      firebase.initializeApp(window.FIREBASE_CONFIG);
      DB = firebase.firestore();
      firebase.auth().onAuthStateChanged(user => {
        currentUser = user;
        authReady = true;
        accessDenied = false;
        if(user){
          subscribeOpportunities();
          subscribeIfCollections();
          startPresence();
          subscribeAllowlistIfAdmin();
          subscribeBranding();
        } else {
          if(unsubscribeOpportunities){ unsubscribeOpportunities(); unsubscribeOpportunities=null; }
          if(unsubscribeAllowlist){ unsubscribeAllowlist(); unsubscribeAllowlist=null; }
          if(unsubscribeBranding){ unsubscribeBranding(); unsubscribeBranding=null; }
          unsubscribeIfCollections();
          stopPresence();
          opportunities = [];
          allowlistEmails = [];
          branding = { companyName:'', logoDataUrl:'' };
          recentActivity = [];
          recentActivityOpen = false;
          fundsViewOpen = false; openFundId = null;
        }
        render();
      });
    } else {
      console.warn('Firebase غير مُهيّأ — راجع firebase-config.js. سيتم استخدام تخزين محلي مؤقت (localStorage) في هذا المتصفح فقط.');
      authReady = true; // لا يوجد Firebase => لا حاجة لبوابة تسجيل دخول، الوضع المحلي مفتوح كالمعتاد
      loadLocalBranding();
    }
  }catch(e){ DB = null; authReady = true; console.error('Firebase init failed:', e); }
  claudeReady = true;
  await loadAll();
  render();
}

/* ---------------- utilities ---------------- */
function uid(prefix){ return prefix+'-'+Math.random().toString(36).slice(2,8).toUpperCase(); }
function getPath(obj,path){ return path.split('.').reduce((o,k)=> (o==null?undefined:o[k]), obj); }
function setPath(obj,path,val){
  const parts = path.split('.'); let o = obj;
  for(let i=0;i<parts.length-1;i++){ if(o[parts[i]]==null) o[parts[i]]={}; o = o[parts[i]]; }
  o[parts[parts.length-1]] = val;
}
function n(v,d){ v = parseFloat(v); return isFinite(v)? v : (d==null?0:d); }
function fmtSAR(v){
  if(v==null || !isFinite(v)) return '—';
  const sign = v<0? '-':''; v = Math.abs(v);
  const s = v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(LANG==='en') return sign+s+' '+T('ر.س','SAR');
  return '\u202B\u2066'+sign+s+'\u2069 '+T('ر.س','SAR')+'\u202C';
}
function fmtNum(v,dec){ if(v==null||!isFinite(v)) return '—'; return v.toLocaleString('en-US',{maximumFractionDigits:dec==null?0:dec, minimumFractionDigits:dec==null?0:dec}); }
function fmtPct(v,dec){ if(v==null||!isFinite(v)) return '—'; const n=(v*100).toFixed(dec==null?1:dec); return LANG==='en' ? n+'%' : '%'+n; }
function fmtUnit(numStr, unitAr, unitEn){ const unit = T(unitAr, unitEn); if(LANG==='en') return numStr+' '+unit; return '\u202B\u2066'+numStr+'\u2069 '+unit+'\u202C'; }
/* نسخ "نظيفة" من fmtSAR/fmtUnit بلا رموز تحكّم الاتجاه (Bidi) المخصّصة لعرض HTML في المتصفح —
   لاستخدامها حصراً عند كتابة نص داخل ملفات PowerPoint (PptxGenJS) حيث تُسبِّب هذه الرموز الخفية
   ظهور نص ملخبط أو مربعات فارغة بدل الاعتماد على اتجاه الفقرة نفسه (rtlMode) لعرض صحيح. */
function fmtSARplain(v){
  if(v==null || !isFinite(v)) return '—';
  const sign = v<0? '-':''; v = Math.abs(v);
  const s = v.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  return sign+s+' '+T('ر.س','SAR');
}
function fmtUnitPlain(numStr, unitAr, unitEn){ return numStr+' '+T(unitAr, unitEn); }
function esc(s){ return (s==null?'':String(s)).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function todayStr(){ return new Date().toISOString().slice(0,10); }
/* التقويم الهجري — يعتمد على دعم المتصفح المدمج (Intl) بدون أي مكتبة خارجية؛ يعود بسلسلة فاضية بأمان لو غير مدعوم */
function fmtHijri(dateStr){
  try{
    const dt = new Date((dateStr||'')+'T00:00:00');
    if(isNaN(dt.getTime())) return '';
    return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura', { year:'numeric', month:'2-digit', day:'2-digit' }).format(dt);
  }catch(e){ return ''; }
}
function fmtDateBilingual(dateStr){
  if(!dateStr) return '';
  let h = fmtHijri(dateStr);
  /* بعض بيئات ICU (مثل Node/Chrome الحديثة) تُلحق "هـ" تلقائياً ضمن تنسيق التقويم الهجري نفسه؛
     نزيل أي "هـ" موجودة مسبقاً في نهاية القيمة قبل إضافة اللاحقة الموحّدة أدناه، لمنع تكرارها (هـ هـ). */
  if(h) h = h.replace(/[\s\u200f]*ه[ـ.]?\s*$/,'').trim();
  return h? `${dateStr} ${T('م','CE')} — ${h} ${T('هـ','AH')}` : dateStr;
}
function reportDateMeta(d){
  const meta = (d && d.meta) || {};
  const rawAsOf = meta.updatedAt || meta.createdAt || todayStr();
  const asOfDate = String(rawAsOf || todayStr()).slice(0,10) || todayStr();
  const generatedDate = todayStr();
  return {
    asOfDate,
    asOfText: fmtDateBilingual(asOfDate),
    generatedDate,
    generatedText: fmtDateBilingual(generatedDate),
  };
}

