/* توسيع مخطط بيانات الفرصة من ملفات خارجية (Pipeline/Risk/DD/IC/Score/Audit...) دون تعديل
   blankOpportunity() نفسها في كل مرة — كل دالة مسجَّلة تُعيد كائناً بحقول إضافية على مستوى
   الجذر (مثل { pipeline: {...} })، تُدمَج هنا، وتلتقطها withDefaults() تلقائياً للفرص القديمة. */
const _opportunitySchemaExtenders = [];
function registerOpportunitySchemaExtender(fn){ _opportunitySchemaExtenders.push(fn); }
const _blankOpportunityCore = blankOpportunity;
blankOpportunity = function(){
  const base = _blankOpportunityCore();
  _opportunitySchemaExtenders.forEach(fn=>{ try{ Object.assign(base, fn()); }catch(e){ console.error('schema extender error:', e); } });
  return base;
};
