  financing: { ltc:0.60, saibor:0.055, margin:0.025, tenor:5 },
  wacc: { rf:0.045, mrp:0.065, beta:0.95, crp:0.012, sp:0.020, alpha:0.015, marketCap:0.075, growth:0.03 },
  exitCosts: { broker:0.025, legal:0.010, exitFee:0.005 },
