/* =========================================================================
   Canonical financial authority — Phase 2R-3
   -------------------------------------------------------------------------
   The financial economics now live only in src/domain/financial/financial-engine.js.
   core.js keeps the historical public names as compatibility bindings so existing
   UI/features/tests continue to call compute()/withDefaults()/irr()/npvAt() without
   carrying a second implementation. Dependencies remain owned by core for this
   recovery step and are injected explicitly into the shared engine.
   ========================================================================= */
const _financialEngine = createFinancialEngine({
  blankOpportunity,
  TIERS,
  USE_TYPES,
  SITE_FACTORS,
  DEV_REFI_STRATEGY_KEY,
  isResidentialUseType,
});
const { irr, npvAt, withDefaults, compute } = _financialEngine;

function sensitivityRows(o){
  const isDev = o.meta.oppType==='development';
  const isIncome = o.meta.oppType==='income';
  const isLandbank = o.meta.oppType==='landbank';
  const hasBasements = (o.land.basements||0) > 0 && !isLandbank;
  const hasHeightPremium = (o.land.floorHeight||3.6) > 3.6 && !isLandbank;
  const bumps = [
    { key:'land.price', label:T('سعر شراء الأرض (م²)','Land Purchase Price (sqm)'), deltaPct:0.10 },
  ];
  if(!isLandbank){
    bumps.push({ key: isDev?'development.salePrice':'income.rent', label: isDev?T('سعر البيع (م²)','Sale Price (sqm)'):T('سعر الإيجار (م²/سنة)','Rent Price (sqm/yr)'), deltaPct:0.10 });
    bumps.push({ key: isDev?'development.exitCapRate':'wacc.marketCap', label:T('معدل الرسملة عند الخروج','Exit Cap Rate'), deltaAbs:0.01 });
    bumps.push({ key:'financing.saibor', label:T('سعر الفائدة (SAIBOR)','Interest Rate (SAIBOR)'), deltaAbs:0.01 });
    bumps.push({ key:'financing.ltc', label:T('نسبة التمويل (LTC)','Financing Ratio (LTC)'), deltaAbs:0.05 });
    bumps.push({ key:'financing.margin', label:T('هامش التمويل فوق SAIBOR','Financing Margin over SAIBOR'), deltaAbs:0.005 });
  }
  if(isDev){
    bumps.push({ key:'development.buildCost', label:T('تكلفة البناء (م²)','Build Cost (sqm)'), deltaPct:0.08 });
    bumps.push({ key:'development.constructionYears', label:T('مدة الإنشاء (سنوات) — تعجيل/تأخير','Construction Duration (yrs) — accelerate/delay'), deltaAbs:0.5 });
    bumps.push({ key:'development.contingency', label:T('احتياطي الطوارئ الإنشائي (Contingency)','Construction Contingency'), deltaAbs:0.03 });
  }
  if(isIncome){
    bumps.push({ key:'income.occupancy', label:T('نسبة الإشغال','Occupancy Rate'), deltaAbs:0.05 });
    bumps.push({ key:'income.opex', label:T('نسبة المصاريف التشغيلية (OPEX)','Operating Expense Ratio (OPEX)'), deltaAbs:0.03 });
  }
  if(isLandbank){
    bumps.push({ key:'landbank.appreciation', label:T('معدل نمو قيمة الأرض السنوي','Annual Land Appreciation Rate'), deltaAbs:0.02 });
    bumps.push({ key:'landbank.carryAnnual', label:T('تكلفة الحمل السنوية (رسوم/صيانة/فرصة بديلة)','Annual Carry Cost'), deltaPct:0.20 });
    bumps.push({ key:'landbank.holdingYears', label:T('مدة الاحتفاظ (سنوات)','Holding Period (yrs)'), deltaAbs:1 });
  }
  if(hasBasements){
    bumps.push({ key:'land.basementCostPremiumPct', label:T('علاوة تكلفة البدروم الأول','1st Basement Cost Premium'), deltaAbs:0.10 });
    bumps.push({ key:'land.basementDepthEscalationPct', label:T('تصاعد علاوة عمق البدرومات','Basement Depth Escalation'), deltaAbs:0.03 });
  }
  if(hasBasements || hasHeightPremium){
    bumps.push({ key:'land.floorHeightPremiumPct', label:T('علاوة تكلفة ارتفاع الدور','Floor Height Cost Premium'), deltaAbs:0.02 });
  }
  if(!isLandbank){
    bumps.push({ key:'exitCosts.rett', label:T('ضريبة التصرفات العقارية عند الخروج (RETT)','Real Estate Transaction Tax at Exit (RETT)'), deltaAbs:0.01 });
  }
  const base = compute(o,'base');
  return bumps.map(b=>{
    const up = JSON.parse(JSON.stringify(o)); const down = JSON.parse(JSON.stringify(o));
    const cur = getPath(up,b.key);
    if(b.deltaPct!=null){ setPath(up,b.key, cur*(1+b.deltaPct)); setPath(down,b.key, cur*(1-b.deltaPct)); }
    else { setPath(up,b.key, cur+b.deltaAbs); setPath(down,b.key, Math.max(0.001,cur-b.deltaAbs)); }
    return { label:b.label, base:base.equityIRR, down:compute(down,'base').equityIRR, up:compute(up,'base').equityIRR };
  });
}

/* تجميعة أثر الرافعة المالية ورسوم الصندوق على العائد — Return Bridge / Leverage & Fee Impact.
   نُعيد حساب نفس الفرصة بمعزل عن رسوم الصندوق (LTC والدين كما هما) لعزل "أثر الرسوم" عن
   "أثر الرافعة" بأكبر قدر ممكن من الدقة، دون افتراض تفكيك رياضي مثالي (التفاعل بين الأثرين
   طبيعي وموجود دوماً في أي جسر عائد Return Bridge حقيقي). */
function returnBridgeRows(o){
  const c = compute(o,'base');
  const zeroFees = JSON.parse(JSON.stringify(o));
  zeroFees.fees = Object.assign({}, zeroFees.fees, {
    mgmt:0, structuring:0, arrangement:0, acquisition:0, disposition:0, assetMgmt:0,
    regAuditCustodian:0, cmaSetup:0, dueDiligence:0, valuation:0,
  });
  zeroFees.subscription = Object.assign({}, zeroFees.subscription, { subscriptionFee:0 });
  const cNoFees = compute(zeroFees,'base');
  return {
    projectIRR: c.projectIRR,
    leverageEffect: cNoFees.equityIRR - c.projectIRR,
    equityIRRGrossOfFees: cNoFees.equityIRR,
    feeDrag: c.equityIRR - cNoFees.equityIRR,
    equityIRRNet: c.equityIRR,
    moicGrossOfFees: cNoFees.MOIC,
    feeDragMOIC: c.MOIC - cNoFees.MOIC,
    moicNet: c.MOIC,
    ltc: o.financing.ltc, debt: c.debt, equity: c.equity, TPC: c.TPC,
    fundSideFees: c.fundSideFees, investorSideFees: c.investorSideFees, feesPctOfTPC: c.feesPctOfTPC,
  };
}

function scenarioCompareRows(o){
  return [
    {key:'pessimistic', label:'🔴 '+T('متشائم','Pessimistic')+' (Pessimistic)'},
    {key:'base', label:'🔵 '+T('الأساسي','Base')+' (Base)'},
    {key:'optimistic', label:'🟢 '+T('متفائل','Optimistic')+' (Optimistic)'},
  ].map(s=>{
    const c = compute(o, s.key);
    return { label:s.label, key:s.key, irr:c.equityIRR, npv:c.npvProject, moic:c.MOIC, verdict:c.verdict };
  });
}

/* =========================================================================
   توصيات لجنة الاستثمار التفصيلية — IC Detailed Recommendations
   ========================================================================= */
const IC_ACTION_LIBRARY = {
  'Equity IRR': ()=>T('خفّض تكلفة الأرض أو تفاوض على سداد مؤجّل لجزء منها، راجع هيكل الدين (LTC/الهامش)، أو أعد تسعير الإيجار/سعر البيع إذا سمح السوق.','Lower the land cost or negotiate deferred payment for part of it, review the debt structure (LTC/margin), or reprice the rent/sale price if the market allows.'),
  'DSCR': ()=>T('قلّل نسبة LTC، تفاوض على هامش تمويل أقل فوق SAIBOR، أو ارفع صافي الدخل التشغيلي (NOI) بزيادة الإيجار أو تقليل OPEX.','Reduce the LTC ratio, negotiate a lower financing margin over SAIBOR, or raise net operating income (NOI) by increasing rent or cutting OPEX.'),
  'MOIC': ()=>T('مدّد أفق الاحتفاظ بالأصل قبل البيع، حسّن هامش الربح التشغيلي، أو قلّل الرسوم والتكاليف غير الأساسية على الصندوق.','Extend the holding horizon before sale, improve the operating margin, or reduce non-essential fees and costs on the fund.'),
  'Yield on Cost': ()=>T('خفّض تكلفة البناء لكل م²، راجع مزيج الاستخدامات (Unit/Tenant Mix) لرفع متوسط الإيجار، أو قلّل التكاليف الناعمة (Soft Costs).','Lower the build cost per sqm, review the unit/tenant mix to raise average rent, or reduce soft costs.'),
  'Project IRR': ()=>T('راجع الجدول الزمني للإنشاء (تسريع التسليم يرفع IRR غير المموّل) أو خفّض التكلفة الإنشائية الإجمالية.','Review the construction schedule (faster delivery raises unlevered IRR) or lower total construction cost.'),
  'Pre-Leasing': ()=>T('كثّف التسويق قبل بدء الإنشاء أو قدّم حوافز إيجار مبكر (Rent-Free Period) لرفع نسبة التأجير المسبق قبل صرف التمويل البنكي.','Intensify marketing before construction starts or offer early-lease incentives (rent-free period) to raise pre-leasing before bank financing is disbursed.'),
  'Pre-Sale %': ()=>T('كثّف حملات البيع على الخارطة وقدّم حوافز حجز مبكر (خصم أو تسهيل سداد) لبلوغ نسبة ما قبل البيع المطلوبة قبل الترخيص بصرف دفعات حساب الضمان، أو أجّل الدفعة الإنشائية التالية حتى استيفاء النسبة النظامية.','Intensify off-plan sales campaigns and offer early-reservation incentives (discount or flexible payment) to reach the required pre-sale threshold before escrow disbursement is authorized, or delay the next construction-linked draw until the regulatory pre-sale percentage is met.'),
};
function icRecommendations(o, c){
  const recs = [];
  c.checks.forEach(chk=>{
    if(chk.skip || chk.v==null || !isFinite(chk.v)) return;
    if(chk.v >= chk.min) return; // معيار مستوفى — لا حاجة لتوصية
    const valStr = chk.fmt==='pct'? fmtPct(chk.v) : chk.v.toFixed(2)+'×';
    const minStr = chk.fmt==='pct'? fmtPct(chk.min) : chk.min.toFixed(2)+'×';
    const gapStr = chk.fmt==='pct'? ((chk.min-chk.v)*100).toFixed(1)+' '+T('نقطة','pts') : (chk.min-chk.v).toFixed(2)+'×';
    recs.push({ k:chk.k, valStr, minStr, gapStr, action: IC_ACTION_LIBRARY[chk.k]? IC_ACTION_LIBRARY[chk.k]() : T('يحتاج مراجعة تفصيلية من فريق الاستثمار.','Needs detailed review by the investment team.') });
  });
  return recs;
}

/* =========================================================================
   نقاط القوة ونقاط التفاوض — Strengths & Negotiation Points (محرك قواعد تلقائي)
   يفحص أرقام الفرصة الفعلية (compute() + المدخلات) لاستخراج: (أ) نقاط قوة جاهزة لعرضها في مذكرة لجنة
   الاستثمار، و(ب) نقاط تفاوض محددة وقابلة للتنفيذ مع الأطراف المقابلة (البائع، البنك، المقاول، مدير
   الصندوق) — كل نقطة مرتبطة برقم فعلي من الفرصة نفسها، وليست نصائح عامة عائمة.
   ========================================================================= */
function dealStrengthsAndNegotiationPoints(o, c){
  const strengths = [], negotiations = [];
  const type = o.meta.oppType;

  // ---- نقاط القوة ----
  if(isFinite(c.equityIRR) && o.criteria.irrMin!=null && (c.equityIRR - o.criteria.irrMin) >= 0.03){
    strengths.push(T(`عائد حقوق الملكية (Equity IRR) ${fmtPct(c.equityIRR)} يتجاوز الحد الأدنى المعتمد (${fmtPct(o.criteria.irrMin)}) بهامش أمان مريح (+${((c.equityIRR-o.criteria.irrMin)*100).toFixed(1)} نقطة).`,
      `Equity IRR of ${fmtPct(c.equityIRR)} clears the approved minimum (${fmtPct(o.criteria.irrMin)}) with a comfortable safety margin (+${((c.equityIRR-o.criteria.irrMin)*100).toFixed(1)} pts).`));
  }
  if(c.dscrMin!=null && isFinite(c.dscrMin) && o.criteria.dscrMin!=null && (c.dscrMin - o.criteria.dscrMin) >= 0.3){
    strengths.push(T(`تغطية خدمة الدين (DSCR) الدنيا ${c.dscrMin.toFixed(2)}× مريحة فوق الحد الأدنى المعتمد (${o.criteria.dscrMin.toFixed(2)}×) — مساحة أمان جيدة لصدمات الإيراد أو أسعار الفائدة.`,
      `Minimum DSCR of ${c.dscrMin.toFixed(2)}× sits comfortably above the approved minimum (${o.criteria.dscrMin.toFixed(2)}×) — good cushion against revenue or rate shocks.`));
  }
  if(type==='income' && isFinite(c.yieldOnCost)){
    const refNiy = USE_TYPES[o.meta.useType] ? USE_TYPES[o.meta.useType].niy : null;
    if(refNiy!=null && (c.yieldOnCost - refNiy) >= 0.01){
      strengths.push(T(`عائد التكلفة (Yield on Cost) ${fmtPct(c.yieldOnCost)} أعلى من المعيار المرجعي لنوع الاستخدام (${fmtPct(refNiy)}) — فارق تسعير إيجابي (Spread) لصالح الفرصة.`,
        `Yield on Cost of ${fmtPct(c.yieldOnCost)} beats the use-type benchmark NIY (${fmtPct(refNiy)}) — a positive pricing spread in the opportunity's favor.`));
    }
  }
  if(o.financing.ltc>0 && o.financing.ltc<=0.50){
    strengths.push(T(`رافعة مالية محافظة (LTC ${fmtPct(o.financing.ltc)}) — مخاطرة تمويلية منخفضة نسبياً، ومساحة للتفاوض على رفع الرافعة إن رغب الصندوق (انظر نقاط التفاوض).`,
      `Conservative leverage (LTC ${fmtPct(o.financing.ltc)}) — relatively low financing risk, with room to negotiate higher leverage if the fund wants it (see negotiation points).`));
  }
  if(type==='income' && o.income.tenantConc!=null && o.income.tenantConc<=0.15){
    strengths.push(T(`تركّز مستأجرين منخفض (${fmtPct(o.income.tenantConc)} لأكبر مستأجر) — مخاطرة إخلاء/تفاوض محدودة مقارنة بمبنى ذي مستأجر مهيمن.`,
      `Low tenant concentration (${fmtPct(o.income.tenantConc)} for the largest tenant) — limited vacancy/renegotiation risk compared to a building with a dominant tenant.`));
  }
  if(type==='income' && o.income.wale!=null && o.income.wale>=5){
    strengths.push(T(`متوسط العمر المتبقي للعقود (WALE) ${o.income.wale.toFixed(1)} سنة — دخل مؤجَّر مستقر نسبياً على المدى المتوسط.`,
      `Weighted Average Lease Expiry (WALE) of ${o.income.wale.toFixed(1)} years — relatively stable leased income over the medium term.`));
  }
  if(isFinite(c.MOIC) && c.MOIC>=2){
    strengths.push(T(`مضاعف رأس المال (MOIC) ${c.MOIC.toFixed(2)}× — مضاعفة رأس المال المستثمر مرتين أو أكثر على مدى عمر الفرصة.`,
      `Equity Multiple (MOIC) of ${c.MOIC.toFixed(2)}× — invested capital doubles or more over the opportunity's life.`));
  }
  if(!strengths.length){
    strengths.push(T('لا توجد نقاط قوة بارزة تتجاوز الحد الأدنى بهامش كبير حالياً — الفرصة قريبة من عتبات القبول دون هامش أمان إضافي واضح.','No standout strengths clear the minimum thresholds by a wide margin right now — the opportunity sits close to the acceptance thresholds without a clear extra safety margin.'));
  }

  // ---- نقاط التفاوض (مبنية على تحليل الحساسية + هيكل التكلفة/التمويل الفعلي) ----
  let maxImpact = null;
  try{
    sensitivityRows(o).forEach(s=>{
      const impact = Math.max(Math.abs((s.up||0)-(s.base||0)), Math.abs((s.down||0)-(s.base||0)));
      if(isFinite(impact) && (!maxImpact || impact>maxImpact.impact)) maxImpact = {label:s.label, impact};
    });
  }catch(e){ /* تحليل الحساسية قد يفشل لمدخلات ناقصة جداً — نتجاهله بأمان هنا فقط */ }
  if(maxImpact && maxImpact.impact>0.005){
    negotiations.push(T(`أكثر متغيّر يؤثر على العائد حسب تحليل الحساسية هو "${maxImpact.label}" (فرق حتى ${(maxImpact.impact*100).toFixed(1)} نقطة IRR) — هذا أول بند يستحق التركيز عليه في التفاوض قبل أي بند آخر.`,
      `The variable with the largest sensitivity impact on IRR is "${maxImpact.label}" (up to ${(maxImpact.impact*100).toFixed(1)} pts IRR swing) — this is the first item worth focusing negotiation on.`));
  }
  if(c.TPC>0 && c.landCost>0){
    const landSharePct = c.landCost/c.TPC;
    if(landSharePct>=0.35){
      negotiations.push(T(`تكلفة الأرض تمثّل ${fmtPct(landSharePct)} من إجمالي تكلفة المشروع (TPC) — حصة مرتفعة نسبياً، ما يجعلها أولوية تفاوضية مع البائع (خصم سعري مباشر، سداد مؤجل لجزء من الثمن، أو ربط جزء منه بأداء المشروع).`,
        `Land cost is ${fmtPct(landSharePct)} of Total Project Cost (TPC) — a relatively high share, making it a priority negotiation point with the seller (a direct price discount, deferred payment on part of the price, or tying part of it to project performance).`));
    }
  }
  if(o.financing.ltc>0 && o.financing.margin>=0.03){
    negotiations.push(T(`هامش البنك الحالي (${fmtPct(o.financing.margin)} فوق SAIBOR) في النطاق الأعلى نسبياً — يستحق طرح التمويل على أكثر من بنك للمنافسة، خصوصاً مع مؤشرات تغطية الدين الحالية.`,
      `The current bank margin (${fmtPct(o.financing.margin)} over SAIBOR) is on the higher side — worth shopping the financing across multiple banks, especially given the current debt coverage metrics.`));
  }
  if(o.financing.ltc>0 && o.financing.ltc<0.55 && type!=='landbank' && (c.dscrMin==null || !isFinite(c.dscrMin) || c.dscrMin >= (o.criteria.dscrMin||1.2)+0.5)){
    negotiations.push(T(`نسبة التمويل بالدين الحالية (LTC ${fmtPct(o.financing.ltc)}) محافظة، وتغطية خدمة الدين تتحمّل على الأرجح رافعة أعلى — فرصة للتفاوض مع البنك على رفع LTC أو تخفيض الهامش مقابل نفس مستوى المخاطرة المُقدَّرة.`,
      `The current LTC (${fmtPct(o.financing.ltc)}) is conservative, and debt coverage likely tolerates more leverage — an opportunity to negotiate a higher LTC or a lower margin for the same estimated risk level.`));
  }
  if(type!=='landbank' && o.financing.ltc>0 && (o.financing.amortType||'interest_only')==='interest_only'){
    negotiations.push(T('هيكل القرض الحالي "فوائد فقط ثم بالون كامل" يحمّل كل مخاطرة سداد أصل الدين على سنة الخروج — يستحق التفاوض مع البنك على جدول استهلاك جزئي (Partial Amortization) لتخفيف حجم البالون، أو تخفيض الهامش مقابل قبول هذا الخطر.',
      'The current "interest-only / full balloon" loan structure loads all principal-repayment risk onto the exit year — worth negotiating a partial amortization schedule with the bank to reduce the balloon size, or a lower margin in exchange for accepting this risk.'));
  }
  const exitCostPct = (o.exitCosts.broker||0)+(o.exitCosts.legal||0)+(o.exitCosts.rett||0)+(o.exitCosts.exitFee||0)+(o.fees.disposition||0);
  if(type!=='landbank' && exitCostPct>=0.08){
    negotiations.push(T(`إجمالي تكاليف التصرف عند الخروج (سمسرة + قانونية + RETT + رسوم تصرف) ${fmtPct(exitCostPct)} من قيمة البيع — عبء مرتفع نسبياً، يستحق التفاوض على تخفيض عمولة السمسرة أو دراسة قنوات بيع مباشرة تقلّل الوسطاء.`,
      `Total exit/disposition costs (broker + legal + RETT + disposition fee) are ${fmtPct(exitCostPct)} of sale value — a relatively heavy load, worth negotiating down the brokerage commission or exploring direct sale channels that reduce intermediaries.`));
  }
  if(isFinite(c.feesPctOfTPC) && c.feesPctOfTPC>=0.06){
    negotiations.push(T(`إجمالي رسوم الصندوق ${fmtPct(c.feesPctOfTPC)} من TPC — يستحق مراجعة هيكل الرسوم مع مدير الصندوق (خصوصاً الرسوم المتكررة كإدارة الصندوق وإدارة الأصول) قبل الإغلاق النهائي.`,
      `Total fund-side fees are ${fmtPct(c.feesPctOfTPC)} of TPC — worth revisiting the fee structure with the fund manager (especially recurring fees like management and asset management fees) before final close.`));
  }
  if(c.basementCostAmt>0 && (c.basementLevels||0)>=2){
    negotiations.push(T('علاوة تكلفة البدروم مرتفعة نسبياً في الافتراضات الحالية — يستحق التفاوض مع المقاول على طريقة تنفيذ بديلة (Top-down أو جدار حجز Diaphragm Wall) قد تخفّض العلاوة الفعلية.',
      'The basement cost premium is relatively high in the current assumptions — worth negotiating with the contractor over an alternative construction method (top-down or diaphragm wall) that may lower the actual premium.'));
  }
  if(!negotiations.length){
    negotiations.push(T('لا توجد نقاط تفاوض بارزة تتجاوز العتبات المعتادة حالياً حسب المدخلات المُدرجة.','No standout negotiation points clear the usual thresholds right now based on the entered inputs.'));
  }

  return { strengths, negotiations };
}

/* =========================================================================
   أفكار تحسين القيمة — Value Enhancer Ideas (استشارية، تحتاج مراجعة هندسية/تنظيمية)
   ========================================================================= */
function valueEnhancerIdeas(o){
  const type = o.meta.oppType;
  const ideas = [];
  if(type==='income' || type==='development'){
    ideas.push(T('إضافة بلكونات/تراسات مكشوفة للوحدات — في عدد من الأنظمة البلدية لا تُحسب (أو تُحسب جزئياً فقط) ضمن معامل البناء الأساسي (FAR)، وترفع القيمة التسويقية دون استهلاك حق بناء كامل — استخدم حقل "مساحات معفاة تقديرية" في خطوة الأرض لحساب الأثر المحتمل تقديرياً، بعد تأكيد النسبة الفعلية من كود البناء المحلي.',
      'Add balconies/open terraces to the units — a number of municipal codes do not count them (or only partially) toward the base building ratio (FAR), raising marketable value without consuming full built-up rights — use the "estimated exempt areas" field in the land step to estimate the potential impact, after confirming the actual percentage from the local building code.'));
    ideas.push(T('استغلال السطح (Roof Utilization) — غرف خدمات مؤجرة، أو مساحات لوحات إعلانية/معدات اتصالات كدخل إضافي هامشي منخفض التكلفة.','Roof utilization — leased utility rooms, or billboard/telecom-equipment space as low-cost incremental income.'));
    ideas.push(T('مراجعة مزيج الوحدات (Unit/Tenant Mix) لصالح الأحجام أو الأنشطة الأعلى طلباً محلياً، بما يرفع متوسط الإيجار أو سعر البيع للمتر.','Review the unit/tenant mix in favor of sizes or activities with higher local demand, raising the average rent or per-sqm sale price.'));
  }
  ideas.push(T('التفاوض على سداد مؤجّل لجزء من ثمن الأرض (Deferred Land Payment) لتخفيف رأس المال المبدئي المطلوب ورفع Equity IRR.','Negotiate deferred payment for part of the land price to reduce required upfront capital and raise Equity IRR.'));
  ideas.push(T('دراسة استراتيجية خروج مختلطة (بيع جزئي + تأجير الباقي) لتحسين التوازن بين السيولة الفورية والعائد المتكرر طويل الأجل.','Study a mixed exit strategy (partial sale + leasing the rest) to improve the balance between immediate liquidity and long-term recurring return.'));
  if(type==='development'){
    ideas.push(T('تسريع الجدول الإنشائي (مقاول/طريقة بناء أسرع) لتقليل فترة رسملة التمويل ورفع IRR غير المموّل (Project IRR).','Accelerate the construction schedule (contractor/faster build method) to shorten the interest-capitalization period and raise the unlevered IRR (Project IRR).'));
  }
  if(type==='landbank'){
    ideas.push(T('متابعة التغييرات التنظيمية/التصنيفية المرتقبة (Zoning) في المنطقة — أي ترقية تصنيف تزيد القيمة السوقية جوهرياً دون أي تكلفة تنموية إضافية.','Track upcoming zoning changes in the area — any zoning upgrade substantially raises market value with no additional development cost.'));
    ideas.push(T('دراسة تقسيم الأرض (Subdivision) لبيعها على قطع أصغر بسعر متر أعلى من البيع كقطعة واحدة، إن سمح النظام العمراني.','Study subdividing the land to sell it as smaller parcels at a higher per-sqm price than selling it as one piece, if the urban planning code allows it.'));
  }
  return ideas;
}

/* =========================================================================
   التوصيات الاستثمارية — Scenario Optimizer (بحث شبكي على عدة روافع مالية)
   يحترم الحد الأدنى لـ DSCR كقيد أساسي، ولا يقترح أي تعديل على حقوق البناء
   النظامية — فقط روافع مالية/تسعيرية ضمن تحكم الفريق.
   ========================================================================= */
function runOptimizer(o){
  const base = compute(o, 'base');
  const isDev = o.meta.oppType==='development';
  const ltcOptions = [o.financing.ltc, 0.55, 0.60, 0.65, 0.70].filter((v,i,a)=>a.indexOf(v)===i);
  const landDeltaOptions = [0, -0.05, -0.10];
  const priceDeltaOptions = [0, 0.03, 0.05];
  const candidates = [{ ltc:o.financing.ltc, landD:0, priceD:0, irr:base.equityIRR, moic:base.MOIC, dscr:base.dscrMin }];
  ltcOptions.forEach(ltc=>{
    landDeltaOptions.forEach(landD=>{
      priceDeltaOptions.forEach(priceD=>{
        if(ltc===o.financing.ltc && landD===0 && priceD===0) return; // نفس الوضع الحالي
        const clone = JSON.parse(JSON.stringify(o));
        clone.financing.ltc = Math.min(0.80, Math.max(0.30, ltc));
        clone.land.price = clone.land.price * (1+landD);
        if(isDev) clone.development.salePrice *= (1+priceD);
        else clone.income.rent *= (1+priceD);
        let cc;
        try{ cc = compute(clone, 'base'); }catch(e){ return; }
        if(!isFinite(cc.equityIRR)) return;
        const dscrOk = cc.dscrMin==null || cc.dscrMin >= (o.criteria.dscrMin||0);
        if(!dscrOk) return;
        candidates.push({ ltc:clone.financing.ltc, landD, priceD, irr:cc.equityIRR, moic:cc.MOIC, dscr:cc.dscrMin });
      });
    });
  });
  candidates.sort((a,b)=>b.irr-a.irr);
  return { base, best: candidates[0]||null, triedCount: candidates.length };
}

/* =========================================================================
   واجهة الإدخال — Field builder helpers
   ========================================================================= */
// نجمة حمراء صغيرة بجانب تسمية أي حقل "ضروري" (opts.required=true) — تشير إلى أن هذا
// الحقل يمس الحساب أو النسب مباشرة، ولم يعد له قيمة افتراضية جاهزة (صُفِّر عمداً — راجع
// blankOpportunity أعلاه) بل يجب على المستخدم تعبئته بنفسه حسب معطيات المشروع الفعلية.
function reqStar(opts){
  return opts && opts.required
    ? `<span class="req-star" title="${T('حقل ضروري — يؤثر مباشرة في الحساب/النسب','Required field — directly affects the calculation/ratios')}">*</span>`
    : '';
}
const F = {
  num(path,label,labelEn,val,opts={}){
    return `<div class="field ${opts.span2?'span2':''} ${opts.required?'is-required':''}"><label><span>${T(label,labelEn||label)}${reqStar(opts)}</span>${LANG==='ar'&&labelEn?`<span class="en">${labelEn}</span>`:''}</label>
      <div class="suffix-wrap"><input type="number" name="${path}" value="${val==null?'':val}" step="${opts.step||'any'}"
        ${opts.min!=null?'min="'+opts.min+'"':''} ${opts.max!=null?'max="'+opts.max+'"':''}>
        ${opts.suffix?'<span class="suffix">'+opts.suffix+'</span>':''}</div>
      ${opts.hint?'<div class="hint">'+opts.hint+'</div>':''}</div>`;
  },
  pct(path,label,labelEn,val,opts={}){
    return `<div class="field ${opts.span2?'span2':''} ${opts.required?'is-required':''}"><label><span>${T(label,labelEn||label)}${reqStar(opts)}</span>${LANG==='ar'&&labelEn?`<span class="en">${labelEn}</span>`:''}</label>
      <div class="suffix-wrap"><input type="number" data-pct="1" name="${path}" value="${(val*100).toFixed(opts.dec==null?2:opts.dec)}" step="${opts.step||'0.1'}">
        <span class="suffix">%</span></div>
      ${opts.hint?'<div class="hint">'+opts.hint+'</div>':''}</div>`;
  },
  select(path,label,labelEn,val,options,opts={}){
    // options: array of [label,value]
    const opts_html = options.map(([lab,v])=>`<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${lab}</option>`).join('');
    return `<div class="field ${opts.span2?'span2':''}"><label><span>${T(label,labelEn||label)}</span>${LANG==='ar'&&labelEn?`<span class="en">${labelEn}</span>`:''}</label>
      <select name="${path}" ${opts.isInt?'data-int="1"':''} ${opts.rerender?'data-rerender="1"':''}>${opts_html}</select>
      ${opts.hint?'<div class="hint">'+opts.hint+'</div>':''}</div>`;
  },
  text(path,label,labelEn,val,opts={}){
    return `<div class="field ${opts.span2?'span2':''}"><label><span>${T(label,labelEn||label)}</span>${LANG==='ar'&&labelEn?`<span class="en">${labelEn}</span>`:''}</label>
      <input type="text" name="${path}" value="${esc(val||'')}" placeholder="${opts.placeholder||''}">
      ${opts.hint?'<div class="hint">'+opts.hint+'</div>':''}</div>`;
  },
  textarea(path,label,labelEn,val,opts={}){
    return `<div class="field span2"><label><span>${T(label,labelEn||label)}</span>${LANG==='ar'&&labelEn?`<span class="en">${labelEn}</span>`:''}</label>
      <textarea name="${path}" placeholder="${opts.placeholder||''}">${esc(val||'')}</textarea></div>`;
  },
  checkbox(path,label,labelEn,val,opts={}){
    return `<div class="field"><label><span>${T(label,labelEn||label)}</span>${LANG==='ar'&&labelEn?`<span class="en">${labelEn}</span>`:''}</label>
      <select name="${path}" data-bool="1" ${opts.rerender?'data-rerender="1"':''}><option value="true" ${val?'selected':''}>${T('نعم — Yes','Yes')}</option><option value="false" ${!val?'selected':''}>${T('لا — No','No')}</option></select></div>`;
  }
};

// حقول "البيع المباشر" (تمييز مشترٍ كاش عن مشترٍ بتمويل عقاري بنكي) — مشتركة بين خطوة التطوير (بيع عادي
// غير على الخارطة) وخطوة الدخل (استراتيجية مختلطة)، حيثما وُجدت نسبة بيع فعلية لمشترين.
function directSaleFieldsHtml(d){
  const ds = d.strategy.directSale||{bankFinancedPct:0, collectionLagYears:1};
  return `
    <p class="step-sub" style="margin-top:16px;">${T('البيع المباشر — كاش أم تمويل بنكي؟','Direct Sale — Cash or Bank-Financed?')}</p>
    <div class="grid3">
      ${F.pct('strategy.directSale.bankFinancedPct','نسبة المشترين بتمويل عقاري بنكي','Bank-financed buyers %', ds.bankFinancedPct, {dec:0, rerender:true, hint:'الباقي (١٠٠٪ - النسبة) يُفترض تحصيله كاش فور التعاقد. صفر = كل المشترين كاش (السلوك السابق دون تغيير)'})}
      ${ds.bankFinancedPct>0? F.num('strategy.directSale.collectionLagYears','تأخير تحصيل حصة التمويل البنكي','Collection lag (bank-financed portion)', ds.collectionLagYears, {suffix:'سنة', hint:'الفارق الزمني الفعلي بين التعاقد وتحويل مبلغ التمويل من البنك للمطوّر (عادة أشهر — يُقرَّب هنا لأقرب سنة كاملة لتوافق نموذج التدفقات السنوي)'}) : ''}
    </div>
    <p class="note" style="margin-top:8px;">${T('عند التفعيل: تُحسم حصة المشترين بالتمويل البنكي (من صافي عائد البيع فقط) من سنة الخروج وتُضاف كدفعة منفصلة بعد التأخير المحدد — يُبرز أثر بطء إجراءات التمويل البنكي على IRR (لا على مضاعف رأس المال الإجمالي MOIC، الذي يبقى كما هو لأن إجمالي المبلغ المُحصَّل لا يتغيّر، فقط توقيته). معطَّلة افتراضياً (٠٪) — لا تأثير على أي فرصة موجودة ما لم تُفعَّل صراحةً.','When enabled: the bank-financed buyers\' share (of net sale proceeds only) is deducted from the exit year and added as a separate payment after the specified lag — this highlights the effect of slow bank financing procedures on IRR (not on total MOIC, which is unchanged since the total amount collected does not change, only its timing). Disabled by default (0%) — no effect on any existing opportunity unless explicitly enabled.')}</p>`;
}

const OPP_TYPE_INFO = {
  income:      { ic:'🏢', t:'دخل تأجيري', en:'Income-Generating', d:'إيجار مستقر — NIY, إشغال, WALE' },
  development: { ic:'🏗️', t:'تطوير وبيع', en:'Development / Capital Growth', d:'IRR, بيع/تأجير, هامش تطوير' },
  landbank:    { ic:'🗺️', t:'بنك الأراضي', en:'Land Banking', d:'تثمين، تغيير تصنيف، أعلى استخدام' },
};

function siteSelectHtml(path,label,labelEn,key,val){
  const opts = SITE_FACTORS[key].map((o,i)=>[`${o[0]} — ×${o[1].toFixed(2)}`, i]);
  return F.select(path,label,labelEn,val||0,opts,{isInt:true});
}

