/* ---------------- جرس النشاط الحديث ("فرصة جديدة أضافها زميل") ---------------- */
function renderActivityBell(){
  const unread = unreadActivityCount();
  return `
  <span class="activity-bell-wrap">
    <button class="btn btn-sm activity-bell-btn" data-action="toggle-activity-panel" title="${T('نشاط حديث','Recent activity')}">
      🔔${unread>0? ` <span class="activity-badge">${unread>9?'9+':unread}</span>` : ''}
    </button>
    ${recentActivityOpen? renderActivityDropdown() : ''}
  </span>
  `;
}
function renderActivityDropdown(){
  const notifBtn = (typeof Notification==='undefined')
    ? `<div class="note">${T('المتصفح الحالي لا يدعم تنبيهات سطح المكتب.','This browser does not support desktop notifications.')}</div>`
    : notifPermission==='granted'
      ? `<div class="note">🔔 ${T('تنبيهات المتصفح مُفعَّلة — هتوصلك حتى لو التبويب مش مفتوح.','Browser notifications are enabled — you will get them even if the tab is not open.')}</div>`
      : notifPermission==='denied'
        ? `<div class="note">${T('تنبيهات المتصفح مرفوضة — فعّلها من إعدادات المتصفح لهذا الموقع لو حبيت.','Browser notifications are blocked — enable them from the browser settings for this site if you like.')}</div>`
        : `<button class="btn btn-sm" style="width:100%; justify-content:center; margin-bottom:8px;" data-action="request-notif-permission">🔔 ${T('تفعيل تنبيهات المتصفح','Enable Browser Notifications')}</button>`;
  return `
  <div class="activity-dropdown" data-action="overlay-noop">
    <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:8px;">
      <div style="font-size:13px; font-weight:700;">🔔 ${T('نشاط حديث','Recent Activity')}</div>
      ${recentActivity.length? `<button class="btn btn-sm btn-ghost" data-action="activity-mark-all-read" style="font-size:11px;">${T('تعليم الكل كمقروء','Mark All Read')}</button>` : ''}
    </div>
    ${notifBtn}
    ${recentActivity.length ? `
      <div style="display:flex; flex-direction:column; gap:4px; margin-top:8px;">
        ${recentActivity.map(a=>`
          <div class="activity-item ${a.seen?'':'unseen'}" data-action="open-activity-item" data-id="${esc(a.id)}" data-opp="${esc(a.oppId)}">
            <div class="t">${a.seen?'':'🆕 '}${esc(a.name)}</div>
            <div class="m">${T('أضافها','Added by')} ${esc(a.by)} · ${timeAgo(a.at)}</div>
          </div>
        `).join('')}
      </div>
    ` : `<div class="note" style="margin-top:8px;">${T('لسه ما فيه نشاط — هيظهر هنا أي فرصة يضيفها زميل آخر لحظياً.','No activity yet — any opportunity a teammate adds will appear here live.')}</div>`}
  </div>
  `;
}

/* =========================================================================
   واجهة المرحلة 4 — المستثمرون والصناديق (Investors & Funds view)
   ========================================================================= */
function ifField(label, labelEn, name, val, opts){
  opts = opts||{};
  const type = opts.type||'text';
  if(opts.select){
    return `<div class="field"><label><span>${T(label,labelEn||label)}</span></label>
      <select name="${name}" data-if-field="${name}">
        ${opts.select.map(o=>{
          const [lbl,v] = Array.isArray(o)? o : [o,o];
          return `<option value="${esc(v)}" ${String(val)===String(v)?'selected':''}>${esc(lbl)}</option>`;
        }).join('')}
      </select></div>`;
  }
  return `<div class="field"><label><span>${T(label,labelEn||label)}</span></label>
    <input type="${type}" name="${name}" data-if-field="${name}" value="${esc(val==null?'':val)}" ${opts.step?`step="${opts.step}"`:''}></div>`;
}
function ifReadForm(){
  // يقرأ كل حقول النموذج المفتوح حالياً (data-if-field) من الـ DOM إلى ifForm.draft قبل الحفظ.
  document.querySelectorAll('[data-if-field]').forEach(el=>{
    const path = el.dataset.ifField;
    let v = el.value;
    if(el.type==='number') v = n(v,0);
    setPath(ifForm.draft, path, v);
  });
}
function investorName(id){ const i = STORE.investors.find(x=>x.id===id); return i? i.data.name : T('(محذوف)','(deleted)'); }
function fundName(id){ const f = STORE.funds.find(x=>x.id===id); return f? f.data.name : T('(محذوف)','(deleted)'); }

