function renderIfLedgerTab(){
  const rows = investorLedgerRows();
  const totCommitted = rows.reduce((a,r)=>a+r.committed,0);
  const totPaidIn = rows.reduce((a,r)=>a+r.paidIn,0);
  const totUnfunded = rows.reduce((a,r)=>a+r.unfunded,0);
  const totDist = rows.reduce((a,r)=>a+r.cumDist,0);
  const blendedDpi = totPaidIn>0? totDist/totPaidIn : null;
  return `
  <div class="dash-hero" style="margin-bottom:16px;">
    <div class="dash-hero-card" style="--accent-color:var(--accent);"><span class="icon">🤝</span><div class="l">${T('إجمالي الالتزامات (Committed)','Total Committed')}</div><div class="v" style="font-size:18px;">${fmtSAR(totCommitted)}</div></div>
    <div class="dash-hero-card" style="--accent-color:var(--good);"><span class="icon">💵</span><div class="l">${T('رأس المال المسدَّد (Paid-in)','Paid-in Capital')}</div><div class="v" style="font-size:18px;">${fmtSAR(totPaidIn)}</div></div>
    <div class="dash-hero-card" style="--accent-color:var(--warn);"><span class="icon">⏳</span><div class="l">${T('الالتزام غير المسحوب (Unfunded)','Unfunded Commitment')}</div><div class="v" style="font-size:18px;">${fmtSAR(totUnfunded)}</div></div>
    <div class="dash-hero-card" style="--accent-color:var(--gold);"><span class="icon">📤</span><div class="l">${T('التوزيعات التراكمية','Cumulative Distributions')}</div><div class="v" style="font-size:18px;">${fmtSAR(totDist)}</div></div>
    <div class="dash-hero-card" style="--accent-color:var(--accent);"><span class="icon">📊</span><div class="l">${T('DPI الموزون','Blended DPI')}</div><div class="v">${blendedDpi!=null? blendedDpi.toFixed(2)+'×':'—'}</div></div>
  </div>
  <div class="panel">
    <div class="panel-head"><h2>📒 ${T('دفتر المستثمرين','Investor Ledger')}</h2></div>
    <div class="tablewrap"><table class="db">
      <thead><tr>
        <th>${T('المستثمر','Investor')}</th><th>${T('الفئة','Class')}</th><th>${T('عدد الصناديق','Funds')}</th>
        <th>${T('الالتزام الكلي','Committed')}</th><th>${T('المسدَّد','Paid-in')}</th><th>${T('غير المسحوب','Unfunded')}</th>
        <th>${T('التوزيعات التراكمية','Cum. Distributions')}</th><th>DPI</th><th>RVPI</th><th>TVPI</th>
      </tr></thead>
      <tbody>
        ${rows.length===0? `<tr><td colspan="10" style="text-align:center; color:var(--ink-faint); padding:24px;">${T('لا يوجد مستثمرون بعد','No investors yet')}</td></tr>` : rows.map(r=>`
          <tr>
            <td><b>${esc(r.investor.data.name)}</b></td>
            <td>${esc(r.investor.data.investorClass)}</td>
            <td class="num mono">${r.fundCount}</td>
            <td class="num mono">${fmtSAR(r.committed)}</td>
            <td class="num mono">${fmtSAR(r.paidIn)}</td>
            <td class="num mono">${fmtSAR(r.unfunded)}</td>
            <td class="num mono">${fmtSAR(r.cumDist)}</td>
            <td class="num mono">${r.dpi!=null? r.dpi.toFixed(2)+'×':'—'}</td>
            <td class="num mono">${r.rvpi!=null? r.rvpi.toFixed(2)+'×':'—'}</td>
            <td class="num mono">${r.tvpi!=null? r.tvpi.toFixed(2)+'×':'—'}</td>
          </tr>
        `).join('')}
      </tbody>
    </table></div>
    <p class="note" style="margin-top:10px;">${T('ملاحظة منهجية: RVPI/TVPI تقديرية مبنية على القيمة الإجمالية المُتوقَّعة (equity×MOIC) للأصول المرتبطة بكل صندوق عبر محرك الاحتساب أعلاه — وليست تقييماً مستقلاً معتمَداً (NAV) للصندوق. Committed/Paid-in/Unfunded/التوزيعات مبنية على سجلات فعلية بتواريخ حقيقية (نداءات الرأسمال والتوزيعات).','Methodology note: RVPI/TVPI are estimates based on the projected total value (equity×MOIC) of each fund\'s linked assets via the engine above — not an independently audited fund NAV. Committed/Paid-in/Unfunded/Distributions are built from actual dated records (capital calls and distributions).')}</p>
  </div>`;
}

